async startActivation(spec) {
			const provider = this.expectProvider(spec.provider);
			if (spec.childId !== void 0 && provider.prepareContinuable === void 0) throw new SubagentError("reserved child ids require a local backend", "UNSUPPORTED_CAPABILITY");
			assertSubagentMaxDepth(spec.maxDepth);
			this.assertCapabilities(provider, spec);
			const manager = this.requireManager();
			if (this.ctx.get("agents")?.get(spec.parent.id) !== spec.parent) throw new SubagentError("subagent creation requires the exact live parent agent", "UNAUTHORIZED");
			if (spec.outputSchema !== void 0) assertObjectJsonSchema(spec.outputSchema);
			const prepare = provider.prepareContinuable?.bind(provider);
			if (prepare !== void 0) return manager.startLocal(spec, (request) => {
				this.assertProviderCurrent(provider);
				return prepare(request);
			});
			const start = provider.start.bind(provider);
			return manager.startExternal(spec, (request) => {
				this.assertProviderCurrent(provider);
				return start(request);
			});
		}

manager_impl.source:
async startLocal(spec, prepare) {
        const parent = spec.parent;
        this.assertAdmitting(parent);
        const ancestry = this.ancestryForChild(parent);
        const reservation = this.reserveName(parent, spec.name);
        const path = joinAgentPath(this.pathOf(parent, ancestry.root), reservation.name);
        try {
            return await this.startLocalNamed(spec, prepare, ancestry, reservation, path);
        }
        finally {
            reservation.release();
        }
    }

SubagentActivationSpec.source:
export interface SubagentActivationSpec extends Omit<SubagentStartRequest, 'label' | 'signal'> {
    /** Registered backend to use. */
    readonly provider: string;
    /** Short task label retained in cataloged child membership. */
    readonly label: string;
    /**
     * Requested name, unique among the parent's children: 1–32 lower-case
     * letters, digits, or hyphens starting with a letter, other than `lead`.
     * Omission selects the first free `agent-N`.
     */
    readonly name?: string;
    /** Optional reserved identity for a local child; external backends allocate their own ids. */
    readonly childId?: SessionId;
    /** Cancellation before publication; callers own later cancellation through dispose. */
    readonly signal: AbortSignal;
    /** Parent delivery notifies the model; caller delivery only returns the result. Local children always enter the parent catalog. */
    readonly delivery: 'parent' | 'caller';
}

SubagentActivation.source:
export interface SubagentActivation {
    /** Stable identity of the child. */
    readonly childId: SessionId;
    /**
     * Model-facing name: slash-separated names from the root when every creator
     * below the root is named, otherwise the child Session id.
     */
    readonly name: string;
    /** Accepted inbox message, when the backend has a local inbox. */
    readonly messageId?: MessageId;
    /**
     * Execution result after teardown settles and notifications are sent; capture failures reject.
     * Teardown failures are reported by dispose() without replacing a captured result.
     */
    readonly result: Promise<SubagentResult>;
    /** Stop and release only this activation; rejects on teardown failure. */
    dispose(): Promise<void>;
}
